	@ParameterizedTest
	@CsvSource({ "2,false", "2,true", "6,false", "6,true" })
	void mixedLengthAndNestedTermsSurviveMultipleIndexOrders(int version, boolean inline) throws Exception {
		prepareFormat(version, inline);
		var vf = SimpleValueFactory.getInstance();
		var predicate = vf.createIRI("urn:index:predicate");
		Set<TripleTerm> expected = new HashSet<>();
		for (Value object : new Value[] { vf.createLiteral("short"), vf.createLiteral("long".repeat(100)),
				vf.createLiteral(0), vf.createLiteral(Long.MAX_VALUE),
				vf.createLiteral("18446744073709551615", XSD.UNSIGNED_LONG),
				vf.createLiteral("language", "en") }) {
			var term = vf.createTripleTerm(vf.createIRI("urn:index:inner:" + expected.size()), predicate, object);
			expected.add(term);
			expected.add(vf.createTripleTerm(vf.createIRI("urn:index:nested:" + expected.size()), predicate, term));
		}
		boolean add = true;
		for (String indexes : new String[] { "posc", "ospc", "cpos,posc", null }) {
			SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config(indexes)));
			repository.init();
			try (var connection = repository.getConnection()) {
				if (add) {
					connection.begin();
					for (TripleTerm term : expected) {
						connection.add(vf.createIRI("urn:index:outer:" + term.hashCode()), predicate, term);
					}
					connection.commit();
					add = false;
				}
				ValueStore values = (ValueStore) repository.getValueFactory();
				Set<Value> actual = new HashSet<>();
				try (RecordIterator terms = values.getTripleTerms(-1, -1, -1)) {
					long[] row;
					while ((row = terms.next()) != null) {
						assertTrue(actual.add(values.getValue(row[TripleIndex.CONTEXT_IDX])));
					}
				}
				assertEquals(expected, actual);
				for (TripleTerm term : expected) {
					assertTrue(connection.hasStatement(null, predicate, term, false));
				}
			} finally {
				repository.shutDown();
			}
		}
	}

	@ParameterizedTest
	@CsvSource({ "2,false", "2,true", "6,false", "6,true" })
	void statementIndexesRebuildExactExplicitAndInferredRows(int version, boolean inline) throws Exception {
		prepareFormat(version, inline);
		var vf = SimpleValueFactory.getInstance();
		var predicate = vf.createIRI("urn:index:predicate");
		var context = vf.createIRI("urn:index:context");
		Set<Statement> expected = new HashSet<>();
		for (int index = 0; index < 8; index++) {
			expected.add(vf.createStatement(vf.createIRI("urn:index:subject:" + index), predicate,
					index % 2 == 0 ? vf.createLiteral(index) : vf.createLiteral("row ".repeat(index + 1)),
					index % 2 == 0 ? null : context));
		}
		boolean add = true;
		for (String indexes : new String[] { "spoc,posc,ospc", "cspo,psoc,spoc", "ospc,posc,spoc" }) {
			LmdbStore store = new LmdbStore(directory.toFile(), config(null).setTripleIndexes(indexes));
			SailRepository repository = new SailRepository(store);
			repository.init();
			try (var connection = repository.getConnection()) {
				if (add) {
					connection.begin();
					connection.add(expected);
					connection.commit();
					Set<Statement> inferred = new HashSet<>();
					try (var sink = store.getSailStore().getInferredSailSource().sink(IsolationLevels.NONE)) {
						for (Statement statement : expected) {
							var subject = vf.createIRI(statement.getSubject().stringValue() + ":inferred");
							sink.approve(subject, predicate, statement.getObject(), statement.getContext());
							inferred.add(vf.createStatement(subject, predicate, statement.getObject(),
									statement.getContext()));
						}
						sink.flush();
					}
					expected.addAll(inferred);
					add = false;
				}
				try (var rows = connection.getStatements(null, null, null, true)) {
					assertEquals(expected, QueryResults.asSet(rows));
				}
			} finally {
				repository.shutDown();
			}
			for (String spec : indexes.split(",")) {
				assertEquals(8, LmdbCompatibilityFixtures.nativeTripleEntryCount(directory, spec + spec));
				assertEquals(8, LmdbCompatibilityFixtures.nativeTripleEntryCount(directory, spec + spec + "-inf"));
			}
		}
	}

	@ParameterizedTest
	@CsvSource({ "2,false", "2,true", "6,false", "6,true" })
	void cspoFirstReindexDoesNotResurrectRetiredTripleTerms(int version, boolean inline) throws Exception {
		prepareFormat(version, inline);
		var factory = SimpleValueFactory.getInstance();
		var predicate = factory.createIRI("urn:retired-reindex:predicate");
		var subject = factory.createIRI("urn:retired-reindex:subject");
		var term = factory.createTripleTerm(factory.createIRI("urn:retired-reindex:inner"), predicate,
				factory.createLiteral("retired triple term"));
		LmdbStore store = new LmdbStore(directory.toFile(), config("cspo"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		long termId;
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(subject, predicate, term);
			connection.commit();
			termId = ((ValueStore) repository.getValueFactory()).getId(term);
			assertTrue(termId != LmdbValue.UNKNOWN_ID);
			try (var snapshot = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				connection.begin(IsolationLevels.SNAPSHOT_READ);
				connection.remove(subject, predicate, term);
				connection.commit();
				assertEquals(1, QueryResults.asList(snapshot.getStatements(subject, predicate, term)).size());
			}
		} finally {
			repository.shutDown();
		}
		assertTrue(LmdbCompatibilityFixtures.nativeGet(directory, "retired_ids",
				LmdbCompatibilityFixtures.unsigned(termId)) != null,
				"The original CSPO-first store must retain the real retired owner before reindexing");
		for (String indexes : new String[] { "posc", null }) {
			repository = new SailRepository(new LmdbStore(directory.toFile(), config(indexes)));
			repository.init();
			try (var connection = repository.getConnection()) {
				assertEquals(0, connection.size());
				ValueStore values = (ValueStore) repository.getValueFactory();
				assertEquals(LmdbValue.UNKNOWN_ID, values.getId(term));
				try (RecordIterator terms = values.getTripleTerms(-1, -1, -1)) {
					assertEquals(null, terms.next());
				}
			} finally {
				repository.shutDown();
			}
			assertEquals(0, LmdbCompatibilityFixtures.nativeValueEntryCount(directory, "term-poscterm-posc"));
		}
		assertIndexes(Set.of("spoc", "cspo", "posc"));
	}

	private void prepareFormat(int version, boolean inline) throws Exception {
		persistedVersion = version;
		inlineLiterals = inline;
		if (version == 2) {
			LmdbCompatibilityFixtures.extract("v2-empty-inline-" + inline + ".zip", directory);
		}
	}

	private LmdbStoreConfig config(String termIndexes) {
		return new LmdbStoreConfig("spoc,posc,ospc").setInlineLiterals(inlineLiterals)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setValueHashCacheEnabled(false)
				.setTripleTermIndexes(termIndexes);
	}

	private void writeAndClose(String termIndexes, boolean add) throws Exception {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config(termIndexes)));
		repository.init();
		var vf = SimpleValueFactory.getInstance();
		var predicate = vf.createIRI("urn:index:predicate");
		var term = vf.createTripleTerm(vf.createIRI("urn:index:inner"), predicate, vf.createLiteral("indexed"));
		try (var connection = repository.getConnection()) {
			if (add) {
				connection.begin();
				connection.add(vf.createIRI("urn:index:outer"), predicate, term);
				connection.commit();
			}
			assertTrue(connection.hasStatement(vf.createIRI("urn:index:outer"), predicate, term, false));
			try (RecordIterator terms = ((ValueStore) repository.getValueFactory()).getTripleTerms(-1, -1, -1)) {
				assertTrue(terms.next() != null);
			}
		} finally {
			repository.shutDown();
		}
	}

	private void assertIndexes(Set<String> terms) throws Exception {
		var properties = properties(directory, "store.properties");
		assertEquals(Integer.toString(persistedVersion), properties.getProperty("version"));
		assertEquals(Set.of("spoc", "posc", "ospc"),
				TripleIndex.parseIndexSpecList(properties.getProperty("triple-indexes")));
		assertEquals(terms, TripleIndex.parseIndexSpecList(properties.getProperty("triple-term-indexes")));
	}
